{
  "segment_function": "Define the concept of work, the human artifice, and the durability and objectivity of world things as distinguished from labor and consumption.",
  "claims": [
    {
      "claim": "The work of our hands (homo faber) fabricates the human artifice out of things whose durability and objectivity provide stability and shelter for mortal human life.",
      "claim_type": "author_position",
      "supporting_excerpt": "The work of our hands, as distinguished from the labor of our bodies— homo faber who makes and literally “works upon” 1 as distinguished from the animal laborans which labors and “mixes with”—fabricates the sheer unending variety of things whose sum total constitutes the human artifice.",
      "support_kind": "direct",
      "qualifications": [
        "distinguished from the labor of our bodies and animal laborans"
      ],
      "confidence": 1
    },
    {
      "claim": "Although use involves a wearing-out process through contact with a living organism, destruction is incidental to use rather than inherent to it in the manner of consumption.",
      "claim_type": "author_position",
      "supporting_excerpt": "What distinguishes the most flimsy pair of shoes from mere consumer goods is that they do not spoil if I do not wear them, that they have an independence of their own, however modest, which enables them to survive even for a considerable time the changing moods of their owner.",
      "support_kind": "direct",
      "qualifications": [
        "destruction is incidental to use but inherent in consumption"
      ],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "human artifice",
      "definition": "The sum total of the unending variety of things made and fabricated by homo faber, mostly objects for use that provide stability and solidity for human life."
    },
    {
      "term": "objectivity",
      "definition": "The relative independence and endurance of world things that allow them to withstand the voracious needs and wants of their living makers and users, enabling humans to retrieve their identity."
    }
  ],
  "distinctions": [
    {
      "item_a": "work",
      "item_b": "labor",
      "distinction": "Work is performed by homo faber who makes and works upon things to create the human artifice, whereas labor is performed by the animal laborans which mixes with things."
    },
    {
      "item_a": "use",
      "item_b": "consumption",
      "distinction": "Destruction is incidental to use and wears down durability, whereas destruction is the inherent end and destiny of all things for consumption."
    }
  ],
  "examples": [],
  "objections": [],
  "responses": [],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "Distinction between homo faber and animal laborans",
    "The role of durability and objectivity in stabilizing human life against nature and consumption"
  ]
}

